package com.oibsip.onlineexam.model;
import java.time.*; import java.util.*;
public class ExamSession { private final List<Question> questions; private final Map<Integer,Character> answers=new HashMap<>(); private final Instant start=Instant.now(); private Instant end; private boolean submitted; private boolean automatic; public ExamSession(List<Question> q){questions=List.copyOf(q);} public List<Question> getQuestions(){return questions;} public Map<Integer,Character> getAnswers(){return answers;} public Instant getStart(){return start;} public Instant getEnd(){return end;} public boolean isSubmitted(){return submitted;} public boolean isAutomatic(){return automatic;} public void answer(int id,char a){if(!submitted) answers.put(id,Character.toUpperCase(a));} public void submit(boolean auto){if(submitted)return; submitted=true;automatic=auto;end=Instant.now();} }
